# perf2: generates nmTriSegNear (work/native_maps_runtime.js): the exact inline port of three-mesh-bvh's
# ExtendedTriangle.closestPointToSegment(segment) < r, with three r147 / r149's Line3 / Triangle math written out
# operation for operation (same order, same branches), so nmBlocked answers bit-for-bit as before without the library's
# non-inlined Vector3 calls (each boxed its float result). python3 work/gen_triseg.py prints the function.
def lcp(out,s,e,p,u):
  # Line3(s,e).closestPointToPoint(p, true, out): n=clamp(((e-s).(p-s))/((e-s).(e-s)),0,1); out=(e-s)*n+s
  return (f"const {u}hx={p}x-{s}x,{u}hy={p}y-{s}y,{u}hz={p}z-{s}z,{u}dx={e}x-{s}x,{u}dy={e}y-{s}y,{u}dz={e}z-{s}z,{u}i={u}dx*{u}dx+{u}dy*{u}dy+{u}dz*{u}dz;"
          f"let {u}n=({u}dx*{u}hx+{u}dy*{u}hy+{u}dz*{u}hz)/{u}i;{u}n=Math.max(0,Math.min(1,{u}n));"
          f"{out}x=({e}x-{s}x)*{u}n+{s}x;{out}y=({e}y-{s}y)*{u}n+{s}y;{out}z=({e}z-{s}z)*{u}n+{s}z;")
def at(out,s,e,t): return f"{out}x=({e}x-{s}x)*{t}+{s}x;{out}y=({e}y-{s}y)*{t}+{s}y;{out}z=({e}z-{s}z)*{t}+{s}z;"
def d2(a,b): return f"(({a}x-{b}x)*({a}x-{b}x)+({a}y-{b}y)*({a}y-{b}y)+({a}z-{b}z)*({a}z-{b}z))"
def segseg(l1s,l1e,l2s,l2e):
  # closestPointsSegmentToSegment(l1, l2, t1, t2) (closestPointLineToLine + the clamp cases), then best=min(best, |t1-t2|^2)
  c=[]
  c.append(f"{{const v02x={l1s}x-{l2s}x,v02y={l1s}y-{l2s}y,v02z={l1s}z-{l2s}z,v10x={l1e}x-{l1s}x,v10y={l1e}y-{l1s}y,v10z={l1e}z-{l1s}z,v32x={l2e}x-{l2s}x,v32y={l2e}y-{l2s}y,v32z={l2e}z-{l2s}z;")
  c.append("const d0232=v02x*v32x+v02y*v32y+v02z*v32z,d3210=v32x*v10x+v32y*v10y+v32z*v10z,d3232=v32x*v32x+v32y*v32y+v32z*v32z,d0210=v02x*v10x+v02y*v10y+v02z*v10z,d1010=v10x*v10x+v10y*v10y+v10z*v10z,den=d1010*d3232-d3210*d3210;")
  c.append("let d=den!==0?(d0232*d3210-d0210*d3232)/den:0;const dd=(d0232+d*d3210)/d3232;let t1x,t1y,t1z,t2x,t2y,t2z;")
  c.append("if(d>=0&&d<=1&&dd>=0&&dd<=1){"+at('t1',l1s,l1e,'d')+at('t2',l2s,l2e,'dd')+"}")
  c.append("else if(d>=0&&d<=1){const q=dd<0?0:1;"+at('t2',l2s,l2e,'q')+lcp('t1',l1s,l1e,'t2','a')+"}")
  c.append("else if(dd>=0&&dd<=1){const q=d<0?0:1;"+at('t1',l1s,l1e,'q')+lcp('t2',l2s,l2e,'t1','a')+"}")
  c.append(f"else{{const px=d<0?{l1s}x:{l1e}x,py=d<0?{l1s}y:{l1e}y,pz=d<0?{l1s}z:{l1e}z,p2x=dd<0?{l2s}x:{l2e}x,p2y=dd<0?{l2s}y:{l2e}y,p2z=dd<0?{l2s}z:{l2e}z;let c1x,c1y,c1z,c2x,c2y,c2z;"
           +lcp('c1',l1s,l1e,'p2','a')+lcp('c2',l2s,l2e,'p','b')+
           f"if({d2('c1','p2')}<={d2('c2','p')}){{t1x=c1x;t1y=c1y;t1z=c1z;t2x=p2x;t2y=p2y;t2z=p2z;}}else{{t1x=px;t1y=py;t1z=pz;t2x=c2x;t2y=c2y;t2z=c2z;}}}}")
  c.append(f"const q2={d2('t1','t2')};if(q2<best)best=q2;}}")
  return ''.join(c)
def tcp(p):
  # Triangle(a,b,c).closestPointToPoint(p, out), then best=min(best, |p-out|^2)
  c=[f"{{const p_x={p}x,p_y={p}y,p_z={p}z;let ox,oy,oz;"]
  c.append("const abx=bx-ax,aby=by-ay,abz=bz-az,acx=cx-ax,acy=cy-ay,acz=cz-az,apx=p_x-ax,apy=p_y-ay,apz=p_z-az,d1=abx*apx+aby*apy+abz*apz,d2=acx*apx+acy*apy+acz*apz;")
  c.append("if(d1<=0&&d2<=0){ox=ax;oy=ay;oz=az;}else{const bpx=p_x-bx,bpy=p_y-by,bpz=p_z-bz,d3=abx*bpx+aby*bpy+abz*bpz,d4=acx*bpx+acy*bpy+acz*bpz;")
  c.append("if(d3>=0&&d4<=d3){ox=bx;oy=by;oz=bz;}else{const vc=d1*d4-d3*d2;")
  c.append("if(vc<=0&&d1>=0&&d3<=0){const v=d1/(d1-d3);ox=ax+abx*v;oy=ay+aby*v;oz=az+abz*v;}else{const cpx=p_x-cx,cpy=p_y-cy,cpz=p_z-cz,d5=abx*cpx+aby*cpy+abz*cpz,d6=acx*cpx+acy*cpy+acz*cpz;")
  c.append("if(d6>=0&&d5<=d6){ox=cx;oy=cy;oz=cz;}else{const vb=d5*d2-d1*d6;")
  c.append("if(vb<=0&&d2>=0&&d6<=0){const w=d2/(d2-d6);ox=ax+acx*w;oy=ay+acy*w;oz=az+acz*w;}else{const va=d3*d6-d5*d4;")
  c.append("if(va<=0&&d4-d3>=0&&d5-d6>=0){const w=(d4-d3)/(d4-d3+(d5-d6));ox=bx+(cx-bx)*w;oy=by+(cy-by)*w;oz=bz+(cz-bz)*w;}else{const g=1/(va+vb+vc),v=vb*g,w=vc*g;ox=ax+abx*v+acx*w;oy=ay+aby*v+acy*w;oz=az+abz*v+acz*w;}}}}}}")
  c.append("const q2=(p_x-ox)*(p_x-ox)+(p_y-oy)*(p_y-oy)+(p_z-oz)*(p_z-oz);if(q2<best)best=q2;}")
  return ''.join(c)
body=("function nmTriSegNear(t,L,r){/* perf2: ExtendedTriangle.closestPointToSegment(L) < r, the same arithmetic written out (generated by work/gen_triseg.py; checked against the library in work/test_bvh_alloc.cjs) - the library's non-inlined Vector3 calls boxed every intermediate */"
 "const A=t.a,B=t.b,C=t.c,ax=A.x,ay=A.y,az=A.z,bx=B.x,by=B.y,bz=B.z,cx=C.x,cy=C.y,cz=C.z,S=L.start,E=L.end,sx=S.x,sy=S.y,sz=S.z,ex=E.x,ey=E.y,ez=E.z;let best=Infinity;"
 +segseg('a','b','s','e')+segseg('b','c','s','e')+segseg('c','a','s','e')+tcp('s')+tcp('e')+"return Math.sqrt(best)<r;}")
print(body)
